  // kilit: Modül 2+ dersleri giriş koduyla açılır (kod Telegram botundan, her ay yenilenir)
  function b64(s) { var b = atob(s), u = new Uint8Array(b.length); for (var i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u; }
  function ub64(u) { var s = ''; u = new Uint8Array(u); for (var i = 0; i < u.length; i++) s += String.fromCharCode(u[i]); return btoa(s); }
  function normal(k) { return (k || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); }
  function kilitKur(acilinca) {
    var KK = 'vkAkademiKod', KS = 'vkAkademiAnahtar';
    var form = document.querySelector('.kl-form'), inp = document.getElementById('kod'), msj = document.querySelector('.kl-mesaj');
    var veri = JSON.parse(document.getElementById('kilitVeri').textContent);
    if (!(window.crypto && crypto.subtle)) { msj.textContent = 'Your browser cannot open this lock. Try an up-to-date browser (Chrome, Safari, Edge, Firefox).'; return; }
    function icerikAc(kHam) {
      return crypto.subtle.importKey('raw', kHam, 'AES-GCM', false, ['decrypt'])
        .then(function (k) { return crypto.subtle.decrypt({ name: 'AES-GCM', iv: b64(veri.iv) }, k, b64(veri.v)); })
        .then(function (d) { document.getElementById('kilit').hidden = true; acilinca(new TextDecoder().decode(d)); });
    }
    function kodla(kod) {
      var n = normal(kod), enc = new TextEncoder();
      return Promise.all([crypto.subtle.digest('SHA-256', enc.encode(n)), fetch('/akademi/anahtar.json', { cache: 'no-cache' }).then(function (r) { return r.json(); })])
        .then(function (r) {
          var id = Array.from(new Uint8Array(r[0])).map(function (x) { return x.toString(16).padStart(2, '0'); }).join('').slice(0, 8);
          var e = null; Object.keys(r[1].aylar).forEach(function (a) { if (r[1].aylar[a].id === id) e = r[1].aylar[a]; });
          if (!e) throw new Error('kod');
          return crypto.subtle.importKey('raw', enc.encode(n), 'PBKDF2', false, ['deriveKey']).then(function (b) {
            return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: b64(e.tuz), iterations: r[1].iter, hash: 'SHA-256' }, b, { name: 'AES-GCM', length: 256 }, false, ['decrypt']);
          }).then(function (sk) { return crypto.subtle.decrypt({ name: 'AES-GCM', iv: b64(e.iv) }, sk, b64(e.k)); });
        });
    }
    function dene(kod, sessiz) {
      if (!sessiz) { msj.textContent = 'Unlocking…'; msj.className = 'kl-mesaj'; }
      return kodla(kod).then(function (kHam) {
        try { localStorage.setItem(KK, normal(kod)); sessionStorage.setItem(KS, ub64(kHam)); } catch (e) {}
        return icerikAc(kHam).then(function () { if (!sessiz) olay('kilit-acildi', 'Giriş kodu kabul edildi'); });
      }).catch(function () {
        try { sessionStorage.removeItem(KS); } catch (e) {}
        if (sessiz) { olay('kilit-gorundu', 'Kilitli ders: kod kutusu göründü'); try { localStorage.removeItem(KK); } catch (e) {} msj.textContent = 'Your saved code has expired. Get this month’s code from the bot.'; msj.className = 'kl-mesaj hata'; }
        else { olay('kilit-hatali', 'Hatalı kod girildi'); msj.textContent = 'That code didn’t work. Check the spelling or get this month’s code from the bot again.'; msj.className = 'kl-mesaj hata'; }
      });
    }
    form.addEventListener('submit', function (e) { e.preventDefault(); if (normal(inp.value).length < 8) { olay('kilit-hatali', 'Hatalı kod girildi'); msj.textContent = 'The code should look like VK-XXXX-XXXX.'; msj.className = 'kl-mesaj hata'; return; } dene(inp.value, false); });
    var kayitli = null, ham = null; try { kayitli = localStorage.getItem(KK); ham = sessionStorage.getItem(KS); } catch (e) {}
    if (!ham && !kayitli) olay('kilit-gorundu', 'Kilitli ders: kod kutusu göründü');
    if (ham) icerikAc(b64(ham)).catch(function () { if (kayitli) dene(kayitli, true); else olay('kilit-gorundu', 'Kilitli ders: kod kutusu göründü'); });
    else if (kayitli) { msj.textContent = 'Unlocking…'; dene(kayitli, true); }
  }

