        m.querySelectorAll('li[data-d]').forEach(function (li) { var ok = !q || trk(li.textContent + ' ' + (li.getAttribute('data-k') || '')).indexOf(q) > -1; li.classList.toggle('ara-gizli', !ok); if (ok) g++; });
